const mongoose = require('mongoose');

// C-01 users
const userSchema = new mongoose.Schema(
  {
    email: {
      type: String,
      required: true,
      unique: true,
      lowercase: true,
      trim: true,
      index: true
    },
    password_hash: { type: String, required: true },
    display_name: {
      type: String,
      required: false,
      default: null,
      maxlength: 80,
      trim: true
    },
    created_at: { type: Date, required: true, default: Date.now }
  },
  { versionKey: false }
);

// BR-07: uniqueness is enforced by the database as well as by the handler, so a
// race between two concurrent registrations still ends in exactly one account.
userSchema.index({ email: 1 }, { unique: true });

userSchema.methods.toPublic = function toPublic() {
  return {
    id: String(this._id),
    email: this.email,
    display_name: this.display_name === undefined ? null : this.display_name
  };
};

module.exports = mongoose.models.users || mongoose.model('users', userSchema, 'users');

const mongoose = require('mongoose');

// C-02 notes
const noteSchema = new mongoose.Schema(
  {
    owner_id: {
      type: mongoose.Schema.Types.ObjectId,
      required: true,
      ref: 'users',
      index: true
    },
    title: {
      type: String,
      required: false,
      default: null,
      maxlength: 200,
      trim: true
    },
    body: {
      type: String,
      required: true,
      minlength: 1,
      maxlength: 10000,
      trim: true
    },
    created_at: { type: Date, required: true, default: Date.now },
    updated_at: { type: Date, required: true, default: Date.now },
    deleted_at: { type: Date, default: null }
  },
  { versionKey: false }
);

// Covers the only read pattern this API has: one owner's live notes, newest first.
noteSchema.index({ owner_id: 1, deleted_at: 1, created_at: -1 });

// BR-03 + BR-05 expressed once, so no handler can forget either half of it.
noteSchema.statics.liveFilter = function liveFilter(ownerId, extra) {
  return Object.assign({ owner_id: ownerId, deleted_at: null }, extra || {});
};

noteSchema.methods.toPublic = function toPublic() {
  return {
    id: String(this._id),
    title: this.title === undefined ? null : this.title,
    body: this.body,
    created_at: new Date(this.created_at).toISOString(),
    updated_at: new Date(this.updated_at).toISOString()
  };
};

module.exports = mongoose.models.notes || mongoose.model('notes', noteSchema, 'notes');

const jwt = require('jsonwebtoken');

// BR-01: tokens are stateless and expire; 24h per the contract's expires_in.
const TOKEN_TTL_SECONDS = 86400;

function secret() {
  return process.env.JWT_SECRET || 'pact-local-development-secret';
}

function signToken(userId) {
  return jwt.sign({ sub: String(userId) }, secret(), { expiresIn: TOKEN_TTL_SECONDS });
}

function verifyToken(token) {
  return jwt.verify(token, secret());
}

module.exports = { signToken, verifyToken, TOKEN_TTL_SECONDS };

const MAX_BODY = 10000;
const MAX_TITLE = 200;
const MIN_PASSWORD = 8;
const MAX_PASSWORD = 200;
const MAX_DISPLAY_NAME = 80;
const DEFAULT_PAGE_SIZE = 20;
const MAX_PAGE_SIZE = 100;

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function asString(value) {
  return typeof value === 'string' ? value : null;
}

function fail(errors, field, message) {
  errors.push({ field: field, message: message });
  return null;
}

// BR-07: email is normalised to lowercase here, which is what makes the unique
// index a case-insensitive uniqueness check.
function validateEmail(value, errors) {
  const raw = asString(value);
  if (raw === null || raw.trim() === '') {
    return fail(errors, 'email', 'email is required');
  }
  const email = raw.trim().toLowerCase();
  if (email.length > 254 || !EMAIL_RE.test(email)) {
    return fail(errors, 'email', 'email must be a valid address');
  }
  return email;
}

function validatePassword(value, errors, options) {
  const enforceLength = !options || options.enforceLength !== false;
  const raw = asString(value);
  if (raw === null || raw === '') {
    return fail(errors, 'password', 'password is required');
  }
  if (enforceLength && raw.length < MIN_PASSWORD) {
    return fail(errors, 'password', 'password must be at least ' + MIN_PASSWORD + ' characters');
  }
  if (raw.length > MAX_PASSWORD) {
    return fail(errors, 'password', 'password must be at most ' + MAX_PASSWORD + ' characters');
  }
  return raw;
}

function validateDisplayName(value, errors) {
  if (value === undefined || value === null) return null;
  const raw = asString(value);
  if (raw === null) {
    return fail(errors, 'display_name', 'display_name must be a string');
  }
  const trimmed = raw.trim();
  if (trimmed === '') return null;
  if (trimmed.length > MAX_DISPLAY_NAME) {
    return fail(errors, 'display_name', 'display_name must be at most ' + MAX_DISPLAY_NAME + ' characters');
  }
  return trimmed;
}

function validateTitle(value, errors) {
  if (value === undefined || value === null) return null;
  const raw = asString(value);
  if (raw === null) {
    return fail(errors, 'title', 'title must be a string');
  }
  const trimmed = raw.trim();
  if (trimmed === '') return null;
  if (trimmed.length > MAX_TITLE) {
    return fail(errors, 'title', 'title must be at most ' + MAX_TITLE + ' characters');
  }
  return trimmed;
}

// BR-04: body required, 1..10000 characters measured after trimming.
function validateBody(value, errors) {
  const raw = asString(value);
  if (raw === null) {
    return fail(errors, 'body', 'body is required and must be a string');
  }
  const trimmed = raw.trim();
  if (trimmed.length < 1) {
    return fail(errors, 'body', 'body must not be empty');
  }
  if (trimmed.length > MAX_BODY) {
    return fail(errors, 'body', 'body must be at most ' + MAX_BODY + ' characters');
  }
  return trimmed;
}

function parsePositiveInteger(raw, field, fallback, min, max, errors) {
  if (raw === undefined || raw === null || raw === '') return fallback;
  const candidate = String(Array.isArray(raw) ? raw[0] : raw).trim();
  if (!/^\d+$/.test(candidate)) {
    fail(errors, field, field + ' must be a positive integer');
    return fallback;
  }
  const parsed = Number(candidate);
  if (parsed < min || parsed > max) {
    fail(errors, field, field + ' must be between ' + min + ' and ' + max);
    return fallback;
  }
  return parsed;
}

// BR-09: page size defaults to 20 and is hard-capped at 100.
function validatePagination(query, errors) {
  const source = query && typeof query === 'object' ? query : {};
  const page = parsePositiveInteger(source.page, 'page', 1, 1, 1000000, errors);
  const limit = parsePositiveInteger(source.limit, 'limit', DEFAULT_PAGE_SIZE, 1, MAX_PAGE_SIZE, errors);
  return { page: page, limit: limit };
}

module.exports = {
  MAX_BODY: MAX_BODY,
  MAX_TITLE: MAX_TITLE,
  MIN_PASSWORD: MIN_PASSWORD,
  DEFAULT_PAGE_SIZE: DEFAULT_PAGE_SIZE,
  MAX_PAGE_SIZE: MAX_PAGE_SIZE,
  validateEmail: validateEmail,
  validatePassword: validatePassword,
  validateDisplayName: validateDisplayName,
  validateTitle: validateTitle,
  validateBody: validateBody,
  validatePagination: validatePagination
};

const mongoose = require('mongoose');
const { verifyToken } = require('../utils/token');

function unauthorized(res) {
  // BR-01: one shape of 401, and never any note data alongside it.
  return res.status(401).json({
    error: 'unauthorized',
    message: 'A valid bearer token is required.'
  });
}

// BR-01 + BR-02. Runs in front of every /api/notes route: an invalid or expired
// token is refused before a handler sees the request, and the caller's id is
// pinned onto req.user so owner_id can only ever come from the token.
function requireAuth(req, res, next) {
  const header = req.get('authorization') || '';
  const match = /^Bearer\s+(.+)$/i.exec(header.trim());
  if (!match) {
    return unauthorized(res);
  }

  let payload;
  try {
    payload = verifyToken(match[1].trim());
  } catch (err) {
    return unauthorized(res);
  }

  if (!payload || !payload.sub || !mongoose.isValidObjectId(String(payload.sub))) {
    return unauthorized(res);
  }

  req.user = { id: String(payload.sub) };
  return next();
}

module.exports = requireAuth;

const express = require('express');
const bcrypt = require('bcryptjs');
const User = require('../models/User');
const { signToken, TOKEN_TTL_SECONDS } = require('../utils/token');
const {
  validateEmail,
  validatePassword,
  validateDisplayName
} = require('../utils/validate');

const router = express.Router();
const BCRYPT_COST = 12;

function payloadOf(req) {
  return req.body && typeof req.body === 'object' && !Array.isArray(req.body) ? req.body : {};
}

function unprocessable(res, details) {
  return res.status(422).json({ error: 'unprocessable_entity', details: details });
}

// API-01 POST /api/auth/register
router.post('/api/auth/register', async (req, res, next) => {
  try {
    const payload = payloadOf(req);
    const errors = [];
    const email = validateEmail(payload.email, errors);
    const password = validatePassword(payload.password, errors);
    const displayName = validateDisplayName(payload.display_name, errors);
    if (errors.length > 0) {
      return unprocessable(res, errors);
    }

    // BR-07: an already-registered email is a 409, compared case-insensitively
    // because validateEmail lowercased it.
    const existing = await User.findOne({ email: email }).select({ _id: 1 });
    if (existing) {
      return res.status(409).json({
        error: 'email_already_registered',
        message: 'That email is already registered.'
      });
    }

    const passwordHash = await bcrypt.hash(password, BCRYPT_COST);

    let user;
    try {
      user = await User.create({
        email: email,
        password_hash: passwordHash,
        display_name: displayName,
        created_at: new Date()
      });
    } catch (err) {
      // BR-07 again, this time losing the race against a concurrent registration.
      if (err && err.code === 11000) {
        return res.status(409).json({
          error: 'email_already_registered',
          message: 'That email is already registered.'
        });
      }
      throw err;
    }

    return res.status(201).json({
      user: user.toPublic(),
      token: signToken(user._id),
      expires_in: TOKEN_TTL_SECONDS
    });
  } catch (err) {
    return next(err);
  }
});

// API-02 POST /api/auth/login
router.post('/api/auth/login', async (req, res, next) => {
  try {
    const payload = payloadOf(req);
    const errors = [];
    // Length rules are not enforced on login: an old password that predates a
    // policy change must still be able to sign in, and rejecting on length here
    // would leak which passwords are plausible.
    const email = validateEmail(payload.email, errors);
    const password = validatePassword(payload.password, errors, { enforceLength: false });
    if (errors.length > 0) {
      return unprocessable(res, errors);
    }

    const user = await User.findOne({ email: email });

    // BR-08: unknown email and wrong password must be indistinguishable, in both
    // the response body and — via the dummy compare — in response time.
    const storedHash = user ? user.password_hash : '$2a$12$invalidinvalidinvalidinvalidinvalidinvalidinvalidinvaliduu';
    const passwordMatches = await bcrypt.compare(password, storedHash);
    if (!user || !passwordMatches) {
      return res.status(401).json({
        error: 'invalid_credentials',
        message: 'Email or password is incorrect.'
      });
    }

    return res.status(200).json({
      user: { id: String(user._id), email: user.email },
      token: signToken(user._id),
      expires_in: TOKEN_TTL_SECONDS
    });
  } catch (err) {
    return next(err);
  }
});

module.exports = router;

const express = require('express');
const mongoose = require('mongoose');
const Note = require('../models/Note');
const requireAuth = require('../middleware/auth');
const { validateTitle, validateBody, validatePagination } = require('../utils/validate');

const router = express.Router();

function payloadOf(req) {
  return req.body && typeof req.body === 'object' && !Array.isArray(req.body) ? req.body : {};
}

function unprocessable(res, details) {
  return res.status(422).json({ error: 'unprocessable_entity', details: details });
}

// BR-03 + BR-05 + BR-06: someone else's note, an already-deleted note, a
// malformed id and a note that never existed all look the same from outside, so
// note ids stay non-enumerable.
function notFound(res) {
  return res.status(404).json({ error: 'not_found', message: 'Note not found.' });
}

function noteIdOf(raw) {
  return mongoose.isValidObjectId(raw) ? new mongoose.Types.ObjectId(String(raw)) : null;
}

// API-03 POST /api/notes
router.post('/api/notes', requireAuth, async (req, res, next) => {
  try {
    const payload = payloadOf(req);
    const errors = [];
    const title = validateTitle(payload.title, errors);
    const body = validateBody(payload.body, errors);
    // BR-04: empty or oversized body never reaches the database.
    if (errors.length > 0) {
      return unprocessable(res, errors);
    }

    const now = new Date();
    const note = await Note.create({
      // BR-02: owner_id comes from the verified token. Any owner_id in the
      // request body is simply not read.
      owner_id: req.user.id,
      title: title,
      body: body,
      created_at: now,
      updated_at: now,
      deleted_at: null
    });

    return res.status(201).json(note.toPublic());
  } catch (err) {
    return next(err);
  }
});

// API-04 GET /api/notes
router.get('/api/notes', requireAuth, async (req, res, next) => {
  try {
    const errors = [];
    const paging = validatePagination(req.query, errors);
    // BR-09: a page or limit outside the allowed range is a 422, not a silent clamp.
    if (errors.length > 0) {
      return unprocessable(res, errors);
    }

    // BR-03 + BR-05: the caller's own, non-deleted notes only.
    const filter = Note.liveFilter(req.user.id);
    const results = await Promise.all([
      Note.find(filter)
        .sort({ created_at: -1 })
        .skip((paging.page - 1) * paging.limit)
        .limit(paging.limit),
      Note.countDocuments(filter)
    ]);

    return res.status(200).json({
      items: results[0].map(function (note) { return note.toPublic(); }),
      page: paging.page,
      limit: paging.limit,
      total: results[1]
    });
  } catch (err) {
    return next(err);
  }
});

// API-05 GET /api/notes/:id
router.get('/api/notes/:id', requireAuth, async (req, res, next) => {
  try {
    const id = noteIdOf(req.params.id);
    if (!id) {
      return notFound(res);
    }

    // BR-03 + BR-05 in the query itself, so an ownership check can't be skipped.
    const note = await Note.findOne(Note.liveFilter(req.user.id, { _id: id }));
    if (!note) {
      return notFound(res);
    }

    return res.status(200).json(note.toPublic());
  } catch (err) {
    return next(err);
  }
});

// API-06 DELETE /api/notes/:id
router.delete('/api/notes/:id', requireAuth, async (req, res, next) => {
  try {
    const id = noteIdOf(req.params.id);
    if (!id) {
      return notFound(res);
    }

    const deletedAt = new Date();
    // BR-05: soft delete. BR-06: the deleted_at: null in the filter means an
    // already-deleted note matches nothing, so no write happens and the stored
    // deleted_at timestamp is never overwritten.
    const note = await Note.findOneAndUpdate(
      Note.liveFilter(req.user.id, { _id: id }),
      { $set: { deleted_at: deletedAt, updated_at: deletedAt } },
      { new: true }
    );

    if (!note) {
      return notFound(res);
    }

    return res.status(200).json({
      id: String(note._id),
      deleted_at: new Date(note.deleted_at).toISOString()
    });
  } catch (err) {
    return next(err);
  }
});

module.exports = router;

const express = require('express');
const mongoose = require('mongoose');
const authRoutes = require('./routes/auth');
const noteRoutes = require('./routes/notes');

const app = express();
app.disable('x-powered-by');
app.use(express.json({ limit: '256kb' }));

// API-01, API-02
app.use(authRoutes);
// API-03, API-04, API-05, API-06
app.use(noteRoutes);

app.use(function (req, res) {
  res.status(404).json({ error: 'not_found', message: 'No such endpoint.' });
});

// eslint-disable-next-line no-unused-vars
app.use(function (err, req, res, next) {
  if (err && (err.type === 'entity.parse.failed' || err instanceof SyntaxError)) {
    return res.status(422).json({
      error: 'unprocessable_entity',
      details: [{ field: 'body', message: 'Request body must be valid JSON.' }]
    });
  }
  if (err && err.name === 'ValidationError') {
    return res.status(422).json({
      error: 'unprocessable_entity',
      details: Object.keys(err.errors || {}).map(function (field) {
        return { field: field, message: err.errors[field].message };
      })
    });
  }
  if (err && err.code === 11000) {
    return res.status(409).json({ error: 'conflict', message: 'Resource already exists.' });
  }
  console.error('[api] unhandled error:', err);
  return res.status(500).json({ error: 'internal_error' });
});

const PORT = Number(process.env.PORT || 3000);
const MONGO_URL = process.env.MONGO_URL;

async function start() {
  if (!MONGO_URL) {
    throw new Error('MONGO_URL is not set');
  }
  await mongoose.connect(MONGO_URL);
  console.log('[api] connected to MongoDB');
  return app.listen(PORT, function () {
    console.log('[api] listening on port ' + PORT);
  });
}

if (require.main === module) {
  start().catch(function (err) {
    console.error('[api] failed to start:', err.message);
    process.exit(1);
  });
}

module.exports = { app: app, start: start };
